   "tipo": "script_godot",
   "codice": "extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi correttamente"):
		return
	var door := find_by_name(main, "Door")
	if not check("door", door != null, "Nella scena principale deve esserci il nodo Door"):
		return
	var has_interact := has_function(door, "interact")
	if not check("has_interact", has_interact, "La porta deve avere un metodo interact()"):
		return
	var state_0 = get_prop(door, "is_open", true)
	check("init_false", state_0 == false, "La variabile is_open deve essere inizialmente false")
	call_if_exists(door, "interact")
	var state_1 = get_prop(door, "is_open", false)
	check("toggle_true", state_1 == true, "Dopo la prima interazione is_open deve diventare true")
	call_if_exists(door, "interact")
	var state_2 = get_prop(door, "is_open", true)
	check("toggle_false", state_2 == false, "Dopo la seconda interazione is_open deve tornare false")
",
   "descrizione": "La porta inverte la variabile is_open ogni volta che riceve il comando interact()"
  }
 ],
